using LibraryManager.Data; using LibraryManager.Models; using Microsoft.EntityFrameworkCore; namespace LibraryManager.Services; public class MemberService { public List<Member> All()=>new LibraryDbContext().Members.AsNoTracking().OrderBy(x=>x.LastName).ToList(); public Member Find(int id){using var d=new LibraryDbContext();return d.Members.Find(id);} public Member Register(Member m,int months,PaymentMethod method,string notes=""){using var d=new LibraryDbContext();if(d.Members.Any(x=>x.NationalId==m.NationalId))throw new InvalidOperationException("کد ملی تکراری است.");var now=DateTime.Now;m.MembershipStartDate=now;m.MembershipExpiryDate=now.AddMonths(months);d.Members.Add(m);d.SaveChanges();d.MembershipPayments.Add(new MembershipPayment{MemberId=m.Id,Amount=SettingsService.Fee,PaymentMethod=method,PeriodMonths=months,Notes=notes});d.SaveChanges();return m;} public void Edit(Member m){using var d=new LibraryDbContext();d.Members.Update(m);d.SaveChanges();} public void Renew(int id,int months,PaymentMethod method,string notes=""){using var d=new LibraryDbContext();var m=d.Members.Find(id)??throw new Exception("عضو پیدا نشد");m.MembershipStartDate=DateTime.Now;m.MembershipExpiryDate=(m.MembershipExpiryDate>DateTime.Now?m.MembershipExpiryDate:DateTime.Now).AddMonths(months);d.MembershipPayments.Add(new MembershipPayment{MemberId=id,Amount=SettingsService.Fee,PaymentMethod=method,PeriodMonths=months,Notes=notes});d.SaveChanges();} public void Delete(int id){using var d=new LibraryDbContext();if(d.Loans.Any(x=>x.MemberId==id))throw new Exception("برای این عضو سابقه امانت وجود دارد.");var m=d.Members.Find(id);if(m!=null){d.Remove(m);d.SaveChanges();}} }